  "outcomes": {
    "primary": [
      {
        "description": "Reach is defined as the proportion of eligible MMPs who were offered preventive chemotherapy during the modified MAM campaign. Reach will be assessed using coverage evaluation surveys and reported as the percentage of eligible participants who answered \"Yes\" to receiving an offer of treatment.",
        "measure": "Reach percentage measured as the proportion of eligible mobile and migrant populations (MMPs) offered preventive chemotherapy during the modified mass administration of medicines (MAM) campaign",
        "time_frame": "Baseline ( to estimate reach in the previous MAM) and immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Coverage is defined as the proportion of eligible MMPs who received and swallowed the offered preventive chemotherapy during the modified MAM campaign. Coverage will be assessed using coverage evaluation surveys and reported as the percentage of eligible participants who answered \"Yes.\"",
        "measure": "Coverage percentage measured as the proportion of eligible MMPs who swallowed preventive chemotherapy during the modified MAM campaign",
        "time_frame": "Baseline (previous MAM campaign) and immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Compliance is defined as the proportion of MMPs who swallowed all preventive chemotherapy medicines after receiving them during the modified MAM campaign. Compliance will be assessed using coverage evaluation surveys and reported as the percentage of participants providing affirmative responses.",
        "measure": "Compliance percentage measured as the proportion of MMPs who swallowed all medicines received during the modified MAM campaign",
        "time_frame": "Baseline (previous MAM campaign) and immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Acceptability is defined as the perception among MMPs that the modified MAM strategy is satisfactory, agreeable, and acceptable. Acceptability will be assessed using binary (Yes/No) questions covering the delivery location, timing, and personnel involved in medicine distribution and reported as the percentage of affirmative responses.",
        "measure": "Acceptability rate (%) of the modified MAM strategy among mobile and migrant populations measured using a study-specific binary questionnaire informed by Proctor's Implementation Outcomes Framework",
        "time_frame": "Immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Prevalence will be measured as the proportion of sampled MMP children testing positive for at least one preventive chemotherapy-targeted neglected tropical disease (schistosomiasis, soil-transmitted helminthiasis, lymphatic filariasis, or onchocerciasis) using WHO-recommended diagnostic methods. Disease-specific prevalence will also be reported.",
        "measure": "Prevalence of preventive chemotherapy-targeted neglected tropical diseases among mobile and migrant population children",
        "time_frame": "Baseline (prior to implementation of the modified MAM strategy; within the fourth month of the study)."
      },
      {
        "description": "Adoption is defined as the initial decision or action to employ an innovation or implementation strategy. Adoption of the modified MAM strategy will be assessed as the proportion of planned anchor sites that agree to implement the co-designed modified MAM strategy following the participatory planning process. Adoption will be measured using structured interviews with implementers and reported as the percentage of planned anchor sites providing an affirmative (\"Yes\") response.",
        "measure": "Adoption rate (%) measured as the proportion of planned anchor sites intending to implement the modified mass administration of medicines (MAM) strategy",
        "time_frame": "Immediately following validation of the modified MAM strategy during the final participatory planning meeting (within the fourth month of the study)."
      },
      {
        "description": "Penetration is defined as the extent to which an implementation strategy becomes integrated within the intended service setting. Penetration will be measured as the proportion of planned anchor sites that successfully implement the modified MAM strategy during the intervention period. Data will be collected through monitoring visits and structured interviews and reported as the percentage of planned anchor sites implementing the strategy.",
        "measure": "Penetration rate (%) measured as the proportion of planned anchor sites implementing the modified mass administration of medicines (MAM) strategy",
        "time_frame": "Immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Implementation fidelity is defined as the degree to which the modified MAM strategy is implemented according to the study protocol. Fidelity will be assessed using structured monitoring visits and implementation checklists evaluating adherence to agreed delivery locations, delivery timing, selected personnel, treatment documentation using village registers, and transmission of treatment reports using mobile phones. Results will be reported as the percentage of planned implementation components delivered as intended.",
        "measure": "Implementation fidelity (%) measured as adherence to the planned components of the modified mass administration of medicines (MAM) strategy",
        "time_frame": "Throughout implementation of the modified MAM campaign and immediately after campaign completion (up to 4 weeks after intervention initiation)."
      },
      {
        "description": "Appropriateness is defined as the perceived fit, relevance, or compatibility of an implementation strategy for a particular setting or target population. Appropriateness of the modified MAM strategy will be assessed among mobile and migrant populations (MMPs) and community drug distributors using a study-specific binary (Yes/No) questionnaire covering delivery locations, timing, personnel, treatment documentation, and reporting procedures. Results will be reported as the percentage of respondents providing affirmative (\"Yes\") responses.",
        "measure": "Appropriateness rate (%) of the modified mass administration of medicines (MAM) strategy among mobile and migrant populations and community drug distributors measured using a study-specific binary questionnaire informed by Proctor's Implementation Outcom",
        "time_frame": "Immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Feasibility is defined as the extent to which an implementation strategy can be successfully used or carried out within a particular setting. Feasibility of the modified MAM strategy will be assessed among MMPs and community drug distributors using a study-specific binary (Yes/No) questionnaire. Results will be reported as the percentage of respondents indicating that participation in or implementation of the modified MAM strategy was easy.",
        "measure": "Feasibility rate (%) of the modified mass administration of medicines (MAM) strategy among mobile and migrant populations and community drug distributors measured using a a binary questionnaire informed by Proctor's Implementation Outcomes Framework",
        "time_frame": "Immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Sustainability is defined as the extent to which an implementation strategy can be maintained within routine programme operations over time. Sustainability of the modified MAM strategy will be assessed among implementers using a study-specific binary (Yes/No) questionnaire. Results will be reported as the percentage of implementers indicating that they could continue implementing the modified MAM strategy without additional monitoring or external support.",
        "measure": "Sustainability rate (%) measured as the proportion of implementers able to continue the modified mass administration of medicines (MAM) strategy without additional monitoring or external support",
        "time_frame": "Immediately after completion of the modified MAM campaign (up to 4 weeks after intervention)."
      },
      {
        "description": "Implementation cost is defined as the operational resources required to implement the modified MAM strategy. Costs will be estimated using programme expenditure records, resource utilization data, and structured interviews with implementers. Outcomes will include the total implementation cost, cost by implementation activity, and the average implementation cost per anchor site and per participant treated.",
        "measure": "Implementation cost of the modified mass administration of medicines (MAM) strategy measured using programme expenditure and resource utilization records",
        "time_frame": "From intervention initiation through completion of the modified MAM campaign (approximately 4 weeks)."
      }
    ],
    "secondary": [
      {
        "description": "Spatial migration patterns refer to the movement pathways of MMPs, including places of origin, transit points, temporary settlements, and destinations during a typical annual migration cycle. Spatial migration patterns will be identified through participatory mapping workshops.",
        "measure": "Spatial migration patterns of mobile and migrant populations identified through participatory mapping",
        "time_frame": "Baseline (during participatory workshops conducted prior to implementation of the modified MAM strategy; within the fourth month of the study)."
      },
      {
        "description": "Temporal migration patterns describe the timing, frequency, duration, and seasonality of migration among MMPs during a typical annual cycle. Temporal migration patterns will be identified through participatory mapping workshops.",
        "measure": "Temporal migration patterns of mobile and migrant populations identified through participatory mapping",
        "time_frame": "Baseline (during participatory workshops conducted prior to implementation of the modified MAM strategy; within the fourth month of the study)."
      },
      {
        "description": "Migration drivers are the social, economic, environmental, occupational, cultural, and security-related factors influencing migration decisions and mobility patterns among MMPs. Migration drivers will be identified through participatory mapping workshops.",
