  "nct_id": "NCT04193527",
  "phase": "PHASE3",
  "source": "ClinicalTrials.gov",
  "sponsor": "GE Healthcare",
  "start_date": "2020-06-28",
  "status": "COMPLETED",
  "study_type": "INTERVENTIONAL",
  "summary": "This is a multicenter, open-label, non-controlled, non-randomized, phase 3 clinical study to compare the SPECT findings after a single IV administration of DaTSCAN™ ioflupane (123I) injection for patients with a clinical diagnosis of Parkinsonian syndrome (PS) involving striatal dopaminergic deficit (SDD; specifically, Parkinson's disease \\[PD\\] \\[SDD\\], multiple system atrophy \\[MSA\\] \\[SDD\\] or or progressive supranuclear palsy \\[PSP\\] \\[SDD\\]) as compared with patients with a clinical diagnosis of essential tremor (ET) (no SDD) and age-matched healthy controls.",
  "title": "A Study to Evaluate the Diagnostic Efficacy of DaTSCAN™ Ioflupane (123I) Injection in Single Photon Emission Computed Tomography (SPECT) for the Diagnosis of Parkinsonian Syndrome (PS) in Chinese Patients"
